#[Filter(
  id: "filter_align",
  title: new TranslatableMarkup("Align images"),
  description: new TranslatableMarkup("Uses a <code>data-align</code> attribute on <code>&lt;img&gt;</code> tags to align images."),
  type: FilterInterface::TYPE_TRANSFORM_REVERSIBLE,
)]
class FilterAlign extends FilterBase {

  /**
   * {@inheritdoc}
   */
  function process($text, $langcode) {
    $result = new FilterProcessResult($text);

    if (stristr($text, 'data-align') !== FALSE) {
      $dom = Html::load($text);
      $xpath = new \DOMXPath($dom);
      foreach ($xpath->query('//*[@data-align]') as $node) {
        // Read the data-align attribute's value, then delete it.
        $align = $node->getAttribute('data-align');
        $node->removeAttribute('data-align');

        // If one of the allowed alignments, add the corresponding class.
        if (in_array($align, ['left', 'center', 'right'])) {
          $classes = $node->getAttribute('class');
